list.of.packages <- c("readxl", "magrittr", "ggplot2", "dplyr", "textclean", 
                      "tidyr", "tidytext", "na.tools", "stringr", "smplot2",
                      "gridExtra", "reshape2", "purrr")
new.packages <- list.of.packages[!(list.of.packages %in% installed.packages()[,"Package"])]
if(length(new.packages)) install.packages(new.packages)
lapply(list.of.packages, require, character.only=T)
rm(list.of.packages,new.packages)

directory <- "data/"

# Import tibble generated by translation.r.
BindDevtDocs <- read.table(paste0(directory,"BindDevtDocs.csv"), header=TRUE, quote="\"")

# Preprocess text with functions from the textclean package.
TidyBindDocs = BindDevtDocs %>% 
  select(code, id, Country, translation) %>% 
  mutate(tdtext = tolower(replace_non_ascii
                          (replace_curly_quote
                            (replace_html
                              (replace_url
                                (translation)
                              )))))

doc_words <- TidyBindDocs %>%
  unnest_tokens(word, tdtext) %>%
  count(Country, word, sort=TRUE)

total_words <- doc_words %>%
  group_by(Country) %>%
  summarise(total = sum(n))

## ANALYSIS OF SDG GOALS IN NDPs 
# Create a corpus and tokenise with unnest_tokens
TidyBindDocsCountry <- TidyBindDocs %>% group_by(Country) %>%
  summarise(tdtextCountry = toString(tdtext))
devt_tokens <- TidyBindDocsCountry %>%
  unnest_tokens(word, tdtextCountry) %>%
  count(Country, word, sort=TRUE) 
sdg_words <- word_bank %>% select(Goal, word)
devt_sdg <- inner_join(devt_tokens, sdg_words, by = join_by(word), relationship = "many-to-many")

# Compute SDG term frequencies for each country
total_words_country <- devt_tokens %>% 
  group_by(Country) %>% 
  summarise(total = sum(n))
devt_words_country <- left_join(devt_sdg, total_words_country)

FreqCountryWords <- devt_words_country %>%  
  group_by(Country) %>% 
  mutate(rank = row_number(), 
         term_frequency = n/total) %>%  #Normalisation
  ungroup()

# Calculate global frequency of each SDG goal across NDPs
total_global_words <- total_words %>% summarise(grand_total = sum(total))

devt_words_global <- cross_join(devt_sdg %>% 
                                  group_by(Goal) %>% 
                                  summarise(n_sdg = sum(n)), 
                                total_global_words)

FreqGlobalWords <- devt_words_global %>%
  mutate(term_frequency = n_sdg/grand_total)

# VISUALISE global SDG terms across NDPs
SDGPlanGloballyTf <-FreqGlobalWords %>% mutate(GoalShow = paste("Goal",Goal))
cbbPalette <- c("#e5243b", "#DDA63A", "#4C9F38", "#C5192D", "#FF3A21", "#26BDE2", 
                "#FCC30B", "#A21942", "#FD6925", "#DD1367", "#FD9D24", "#BF8B2E", 
                "#3F7E44", "#0A97D9", "#56C02B", "#00689D", "#19486A")

plotSDGGloballyTf <- ggplot(SDGPlanGloballyTf) +
  geom_hline(aes(yintercept = y), data.frame(y = c(0:3) * 10), color = "lightgrey") + 
