    legend.position = "bottom",
  )

# VISUALISE global SDG plans (highest goal per country)
SDGPlanHighestG <- FreqCountryWords %>%
  group_by(Country, Goal) %>%
  summarise(freqGoal = sum(n), total = mean(total), n = n(), .groups = 'drop') %>%
